 <p>\u547d\u4e2d\u8ba1\u6570\u5668\u548c\u672a\u547d\u4e2d\u8ba1\u6570\u5668\u5171\u7528 {@link #METRIC_NAME}\uff0c\u901a\u8fc7 {@code result} \u6807\u7b7e
 \u533a\u5206\u7ed3\u679c\u7c7b\u578b\uff0c\u5e76\u901a\u8fc7 {@code cache} \u6807\u7b7e\u533a\u5206\u7f13\u5b58\u5b9e\u4f8b\u3002\u4e24\u4e2a\u8ba1\u6570\u5668\u90fd\u4ee5\u7f13\u5b58\u5bf9\u8c61
 \u4f5c\u4e3a\u89c2\u6d4b\u6e90\uff0cMicrometer \u6293\u53d6\u65f6\u5206\u522b\u8c03\u7528 {@link #cacheStats(CaffeineCache)} \u83b7\u53d6
