\u521b\u5efa\u6216\u91cd\u5efa\u6307\u5b9a\u547d\u540d\u7a7a\u95f4\u7684 BloomFilter

 <p>\u7528\u4e8e\u5b9a\u671f\u91cd\u5efa\u8fc7\u6ee4\u5668\uff0c\u6e05\u9664\u8fc7\u671f\u6570\u636e\u5e76\u91cd\u65b0\u52a0\u8f7d\u6709\u6548\u6570\u636e\u3002
@param namespace \u547d\u540d\u7a7a\u95f4
@param expectedInsertions \u9884\u671f\u5143\u7d20\u6570\u91cf
@param fpp \u8bef\u5224\u7387\uff08False Positive Probability\uff09
@return \u65b0\u521b\u5efa\u7684 BloomFilter \u5b9e\u4f8b

\u8bb0\u5f55\u8bef\u5224\uff08\u7531\u4e1a\u52a1\u5c42\u8c03\u7528\uff09

 <p>\u5f53 BloomFilter \u5224\u5b9a key \u53ef\u80fd\u5b58\u5728\uff0c\u4f46\u5b9e\u9645\u67e5\u8be2\u7f13\u5b58\u548c\u6570\u636e\u5e93\u90fd\u4e0d\u5b58\u5728\u65f6\uff0c
 \u4e1a\u52a1\u5c42\u5e94\u8be5\u8c03\u7528\u6b64\u65b9\u6cd5\u8bb0\u5f55\u8bef\u5224\u3002

 <p>\u4f7f\u7528\u793a\u4f8b\uff1a
 <pre>{@code
 if (bloomFilter.mightContain("user", key)) {
     User user = cache.get(key);
     if (user == null) {
         user = db.findById(key);
         if (user == null) {
             // BloomFilter \u8bef\u5224
             bloomFilterMetrics.recordFalsePositive("user");
         }
     }
 }
 }</pre>
