\u5e42\u7b49\u767b\u8bb0\u6e20\u9053\u8eab\u4efd\u7ed1\u5b9a\u3002

 <p>\u5904\u7406\u89c4\u5219\uff1a
 <ul>
   <li>\uff08\u6e20\u9053, OpenID\uff09\u5c1a\u672a\u7ed1\u5b9a \u2192 \u65b0\u5efa\u7ed1\u5b9a\u8bb0\u5f55</li>
   <li>\u5df2\u7ed1\u5b9a\u5230\u540c\u4e00\u7528\u6237 \u2192 \u4ec5\u540c\u6b65 UnionID</li>
   <li>\u5df2\u7ed1\u5b9a\u5230\u5176\u4ed6\u7528\u6237 \u2192 \u8df3\u8fc7\u5e76\u8bb0\u5f55 WARN\uff08\u552f\u4e00\u7ea6\u675f\u515c\u5e95\uff0c\u4e0d\u8986\u76d6\u65e2\u6709\u5f52\u5c5e\uff09</li>
   <li>\u5165\u53c2\u7f3a\u5931\uff08userId/openId \u4e3a\u7a7a\uff09\u2192 \u9759\u9ed8\u8df3\u8fc7</li>
 </ul>
