@return \u65b0\u751f\u6210\u7684\u660e\u6587\u5bc6\u94a5\uff08\u4ec5\u672c\u6b21\u8fd4\u56de\u53ef\u89c1\uff0c\u843d\u5e93\u4e3a\u52a0\u5bc6\u540e\u5bc6\u94a5\uff09\uff1b\u5ba2\u6237\u7aef\u4e0d\u5b58\u5728\u6216\u4e3a public \u5ba2\u6237\u7aef\u65f6 Mono \u4ee5 IllegalArgumentException \u9519\u8bef\u7ec8\u6b62

