 <p>\u6821\u9a8c\u89c4\u5219\uff1apublic \u5ba2\u6237\u7aef\u65e0\u5bc6\u94a5\uff0c\u76f4\u63a5\u89c6\u4e3a\u6709\u6548\uff1b\u5f53\u524d\u5bc6\u94a5\u5339\u914d\u8fd4\u56de true\uff1b
 \u5bc6\u94a5\u5df2\u8fc7\u671f\u8fd4\u56de false \u5e76\u8bb0\u5f55\u8fc7\u671f\u5bc6\u94a5\u4f7f\u7528\u5ba1\u8ba1\u4e8b\u4ef6\uff1b\u5f53\u524d\u5bc6\u94a5\u4e0d\u5339\u914d\u4f46\u65e7\u5bc6\u94a5
 \uff08\u8f6e\u6362\u5bbd\u9650\u671f\u5185\uff09\u5339\u914d\u8fd4\u56de true \u5e76\u8bb0\u5f55\u65e7\u5bc6\u94a5\u4f7f\u7528\u5ba1\u8ba1\u4e8b\u4ef6\uff1b\u5747\u4e0d\u5339\u914d\u8fd4\u56de false
 \u5e76\u8bb0\u5f55\u8ba4\u8bc1\u5931\u8d25\u5ba1\u8ba1\u4e8b\u4ef6\uff1b\u5ba2\u6237\u7aef\u4e0d\u5b58\u5728\u65f6\u8fd4\u56de false\u3002
