 <pre>{@code
 // \u67e5\u8be2\u67d0\u4e2a\u914d\u7f6e\u7684\u6240\u6709\u5386\u53f2\u8bb0\u5f55(\u5206\u9875)
 LambdaQueryWrapper<GenHistoryPO> wrapper = new LambdaQueryWrapper<>();
