@param request \u5e95\u5c42 HTTP \u8bf7\u6c42
@return \u8bf7\u6c42\u5143\u6570\u636e

\u81ea\u52a8\u91cd\u8bd5\u73af\u7ed5\u901a\u77e5\u3002

 <p>\u62e6\u622a\u6240\u6709\u6807\u6ce8 {@link AutoRetry} \u6ce8\u89e3\u7684\u65b9\u6cd5\uff0c\u5c06\u5176\u8fd4\u56de\u503c\u6309\u5f62\u6001\u5206\u53d1\uff1a
