 \u56e0\u6b64\u4e0d\u80fd\u4f18\u5148\u4f9d\u8d56\u57fa\u4e8e ThreadLocal \u7684 MDC\u3002\u8fd9\u91cc\u9996\u5148\u8bfb\u53d6\u4e0d\u53d7\u7ebf\u7a0b\u5207\u6362\u5f71\u54cd\u7684\u4ea4\u6362\u5bf9\u8c61\u5c5e\u6027\uff1b
