\u5b89\u5168\u83b7\u53d6\u8bf7\u6c42\u65b9\u6cd5\u540d\uff08\u7eaf\u51fd\u6570\uff09\u3002

 <p>\u975e\u6807\u51c6\u65b9\u6cd5\uff08\u5982 CONNECT\uff09\u5728 {@link HttpMethod} \u679a\u4e3e\u4e2d\u4e0d\u5b58\u5728\uff0c{@code getMethod()} \u53ef\u80fd
 \u629b\u5f02\u5e38\u6216\u8fd4\u56de null\uff0c\u7edf\u4e00\u8fd4\u56de {@link #UNKNOWN_METHOD} \u907f\u514d\u62e6\u622a\u94fe\u8def\u81ea\u8eab\u62a5\u9519\u3002
 \u8be5\u65b9\u6cd5\u4ec5\u5728\u8ba1\u6570\u5668\u6807\u7b7e\u4e0e\u65e5\u5fd7\u4e2d\u4f7f\u7528\uff0c\u4e0d\u5f71\u54cd\u62e6\u622a\u5224\u5b9a\u7ed3\u679c\u3002
@param request HTTP \u8bf7\u6c42
@return \u65b9\u6cd5\u540d\u6216 UNKNOWN

