@since 2.1.0

\u4ece\u8ba4\u8bc1\u4e0a\u4e0b\u6587\u4e2d\u89e3\u6790\u5f53\u524d\u767b\u5f55\u7528\u6237\u7684\u4e1a\u52a1 ID

 <p>\u5c06\u8ba4\u8bc1\u5c42\u7684 openId \u8f6c\u6362\u4e3a\u4e1a\u52a1\u5c42\u7684\u7528\u6237\u4e3b\u952e ID\u3002\u8be5\u65b9\u6cd5\u5c01\u88c5\u4e86\u4ee5\u4e0b\u4e24\u6b65\u64cd\u4f5c\uff1a
