\u6d41\u7a0b\u56de\u9000\u5230\u6307\u5b9a\u8282\u70b9\u3002

 <p>\u5c06\u5f53\u524d\u4efb\u52a1\u56de\u9000\u5230\u6d41\u7a0b\u4e2d\u7684\u524d\u7f6e\u8282\u70b9\uff0c\u7528\u4e8e\u5904\u7406\u5ba1\u6279\u9a73\u56de\u540e\u9700\u8981\u91cd\u65b0\u5ba1\u6279\u7684\u573a\u666f\u3002
 \u56de\u9000\u64cd\u4f5c\u4f1a\uff1a
 <ul>
   <li>\u5c06\u5f53\u524d\u4efb\u52a1\u6807\u8bb0\u4e3a ROLLED_BACK \u72b6\u6001</li>
   <li>\u5728\u76ee\u6807\u8282\u70b9\u521b\u5efa\u65b0\u7684\u5f85\u529e\u4efb\u52a1</li>
   <li>\u4fdd\u7559\u5b8c\u6574\u7684\u6d41\u8f6c\u8bb0\u5f55\uff0c\u786e\u4fdd\u5ba1\u8ba1\u8ffd\u6eaf</li>
 </ul>

