\u8f6c\u529e\u4efb\u52a1\u7ed9\u5176\u4ed6\u4eba\u3002

 <p>\u5c06\u5f53\u524d\u5f85\u529e\u4efb\u52a1\u8f6c\u4ea4\u7ed9\u5176\u4ed6\u7528\u6237\u5904\u7406\uff0c\u7528\u4e8e\u5904\u7406\u539f\u5ba1\u6279\u4eba\u4e0d\u5728\u6216\u9700\u8981\u4ed6\u4eba\u4ee3\u529e\u7684\u573a\u666f\u3002
 \u8f6c\u529e\u64cd\u4f5c\u4f1a\uff1a
 <ul>
   <li>\u8bb0\u5f55\u539f\u5ba1\u6279\u4eba\u4fe1\u606f\u5230 transferred_from \u5b57\u6bb5</li>
   <li>\u5c06\u4efb\u52a1\u7684 assignee_id \u4fee\u6539\u4e3a\u65b0\u5ba1\u6279\u4eba</li>
   <li>\u4fdd\u7559\u4efb\u52a1\u7684\u5176\u4ed6\u5c5e\u6027\uff08\u72b6\u6001\u3001\u521b\u5efa\u65f6\u95f4\u7b49\uff09</li>
 </ul>

 <h3>\u4f7f\u7528\u793a\u4f8b</h3>
 <pre>{@code
